def backfill_assessment_attempts(apps, schema_editor):
    """
    Backfills existing ModuleQuestionResponse records by creating Attempt 1
    for each (module, learner) pair, linking existing responses, and preserving timestamps.
    """
    ModuleQuestionResponse = apps.get_model('core', 'ModuleQuestionResponse')
    ModuleAssessmentAttempt = apps.get_model('core', 'ModuleAssessmentAttempt')

    # Group responses by (question__module_id, learner_id)
    responses = ModuleQuestionResponse.objects.select_related('question').all()
    attempts_map = {}

    for r in responses:
        mod_id = r.question.module_id
        learner_id = r.learner_id
        key = (mod_id, learner_id)

        if key not in attempts_map:
            attempt = ModuleAssessmentAttempt.objects.create(
                module_id=mod_id,
                learner_id=learner_id,
                attempt_number=1,
                score=1.0 if r.response_value else 0.0,
                total_possible=1.0,
                percentage=100.0 if r.response_value else 0.0,
                is_completed=True,
                started_at=r.submitted_at,
                completed_at=r.submitted_at,
            )
            attempts_map[key] = attempt
        else:
            attempt = attempts_map[key]
            attempt.total_possible += 1.0
            if r.response_value:
                attempt.score += 1.0
            attempt.percentage = round((attempt.score / attempt.total_possible) * 100.0, 1)
            attempt.save(update_fields=['score', 'total_possible', 'percentage'])

        r.attempt = attempts_map[key]
        r.save(update_fields=['attempt'])


